        if all(x == grid[i][0] for x in grid[i]):
            top = grid[:i]
            bottom = grid[i+1:]

            top_flat = [x for row in top for x in row]
            bot_flat = [x for row in bottom for x in row]

            top_counts = Counter(top_flat)
            bot_counts = Counter(bot_flat)

            tp, ts = get_primary_secondary(top_counts)
            bp, bs = get_primary_secondary(bot_counts)

            if tp == bp:  # SAME PRIMARY
                common_primary = tp

                # Based on Demo 2: common_primary=9, new_marker=3, common_primary stays 9
                # Where both top and bottom have common_primary -> marker
                # Else -> common_primary

                result = []
                for r in range(len(top)):
                    row = []
                    for c in range(w):
                        if top[r][c] == common_primary and bottom[r][c] == common_primary:
                            row.append(3)
                        else:
                            row.append(common_primary)
                    result.append(row)
                return result
            else:  # DIFFERENT PRIMARIES
                # Demo 1: top_primary=0, bot_primary=1, common secondary=8
                # Output is all 8s
                # What is common secondary? Need both top and bot to have it
                if ts == bs:
                    common_secondary = ts
                else:
                    # Check if there's any value that appears in both top and bot counts
                    for val in top_counts.keys():
                        if val in bot_counts:
                            common_secondary = val
                            break
                    else:
                        common_secondary = None

                if common_secondary is not None:
                    result = [[common_secondary] * w for _ in range(len(top))]
                    return result
                else:
                    # Fallback - maybe just use secondary from either
                    return [[ts] * w for _ in range(len(top))]

    # Try vertical divider
    for c in range(w):
        col_values = [grid[r][c] for r in range(h)]
        if all(x == col_values[0] for x in col_values):
            left = [row[:c] for row in grid]
            right = [row[c+1:] for row in grid]
            w_left, w_right = len(left[0]), len(left[0]) - 1

            left_flat = [x for row in left for x in row]
            right_flat = [x for row in right for x in row]

            left_counts = Counter(left_flat)
            right_counts = Counter(right_flat)

            tl, ts = get_primary_secondary(left_counts)
            tr, ts = get_primary_secondary(right_counts)

            print(f"Found vertical divider at column {c}")
            print(f"Left: primary={tl}, secondary={ts}")
            print(f"Right: primary={tr}, secondary={ts_right}")

            if tl == tr:
